#!/usr/bin/env Rscript

suppressPackageStartupMessages({ library(optparse); library(jsonlite); library(ggplot2) })
`%||%` <- function(x, y) if (is.null(x) || !length(x) || all(is.na(x))) y else x
op <- parse_args(OptionParser(option_list=list(
  make_option('--input', type='character'), make_option('--params', type='character'),
  make_option('--output', type='character'), make_option('--scores', type='character', default=NULL))))
out <- op$output %||% getwd(); dir.create(out, recursive=TRUE, showWarnings=FALSE)
required <- c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','matrix_data_used.csv','score_data_used.csv','row_order.csv')
unlink(file.path(out, setdiff(required,'run.log'))); if (file.exists(file.path(out,'run.log'))) unlink(file.path(out,'run.log'))
logmsg <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(msg, detail='', suggestion='Check input columns and params.json.') { writeLines(toJSON(list(error=msg,detail=detail,suggestion=suggestion),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); logmsg(paste(msg,detail)); quit(status=1) }
get <- function(p,n,d=NULL) { if (!is.null(p[[n]])) return(p[[n]]); for (s in c('data','order','left','score','layout','interaction','theme')) if (is.list(p[[s]]) && !is.null(p[[s]][[n]])) return(p[[s]][[n]]); d }
vec <- function(x) if (is.null(x)) character() else trimws(as.character(unlist(x,use.names=FALSE)))
one <- function(x,d='') { x<-unlist(x,use.names=FALSE); if(length(x)) as.character(x[1]) else d }
num <- function(x,d) { z<-suppressWarnings(as.numeric(unlist(x,use.names=FALSE)[1])); if(length(z)&&is.finite(z)) z else d }
boo <- function(x,d=FALSE) { if(is.null(x)) return(d); if(is.logical(x)) return(isTRUE(x[1])); tolower(one(x)) %in% c('true','t','yes','y','1','on') }
readtab <- function(path) { if(is.null(path)||!file.exists(path)) fail('Input file not found',as.character(path)); if(tolower(tools::file_ext(path)) %in% c('tsv','txt')) read.delim(path,check.names=FALSE,stringsAsFactors=FALSE) else read.csv(path,check.names=FALSE,stringsAsFactors=FALSE) }
finite_num <- function(x) suppressWarnings(as.numeric(as.character(x)))
fmt <- function(x,d) ifelse(is.na(x),'',formatC(x,format='f',digits=d))
item <- function(x,i,d=NULL) { if(is.null(x)) return(d); if(is.list(x) && !is.data.frame(x)) { if(!is.null(names(x)) && !is.null(x[[i]])) return(x[[i]]); if(length(x)>=i) return(x[[i]]) }; if(length(x)>=i) x[[i]] else d }
named_item <- function(x,nm,i,d=NULL) { if(is.list(x) && !is.null(names(x)) && nm %in% names(x)) x[[nm]] else item(x,i,d) }
as_limits <- function(x,i,values) { z<-if(!is.list(x)&&length(x)==2) as.numeric(x) else as.numeric(unlist(item(x,i,NULL))); if(length(z)!=2) z<-range(values,finite=TRUE); if(length(z)!=2 || !all(is.finite(z))) z<-c(0,1); if(diff(z)==0) z<-z+c(-.5,.5); z }
as_palette <- function(x,i,d) { z<-if(!is.list(x)) vec(x) else vec(item(x,i,NULL)); if(length(z)<2) d else z }

tryCatch({
  if(is.null(op$input)||!file.exists(op$input)) fail('Missing --input',as.character(op$input))
  if(is.null(op$params)||!file.exists(op$params)) fail('Missing --params',as.character(op$params))
  p<-fromJSON(op$params,simplifyVector=FALSE); raw<-readtab(op$input); mode<-tolower(one(get(p,'input_mode','auto')))
  row_col<-one(get(p,'row_column',names(raw)[1]),names(raw)[1]); metric_cols<-vec(get(p,'metric_columns'))
  score_cols<-vec(get(p,'score_columns')); score_col<-one(get(p,'score_column',''),'')
  if(!length(score_cols) && nzchar(score_col)) score_cols<-score_col
  if(!length(score_cols) && 'Overall' %in% names(raw)) score_cols<-'Overall'
  if(mode=='long'||(mode=='auto'&&all(c('row','metric','value')%in%names(raw)))) {
    mode<-'long'; rc<-one(get(p,'row_column','row'),'row'); mc<-one(get(p,'metric_column','metric'),'metric'); vc<-one(get(p,'value_column','value'),'value')
    if(!all(c(rc,mc,vc)%in%names(raw))) fail('Long input columns not found',paste(c(rc,mc,vc),collapse=', '))
    rows<-unique(as.character(raw[[rc]])); metrics<-unique(as.character(raw[[mc]])); if(length(metric_cols)) metrics<-c(intersect(metric_cols,metrics),setdiff(metrics,metric_cols)); mat<-matrix(NA_real_,length(rows),length(metrics),dimnames=list(rows,metrics))
    for(i in seq_len(nrow(raw))) if(as.character(raw[[mc]][i])%in%metrics) mat[as.character(raw[[rc]][i]),as.character(raw[[mc]][i])]<-finite_num(raw[[vc]][i])
    score_mat<-matrix(NA_real_,length(rows),length(score_cols),dimnames=list(rows,score_cols)); for(j in seq_along(score_cols)) if(score_cols[j]%in%names(raw)) for(i in seq_len(nrow(raw))) score_mat[as.character(raw[[rc]][i]),j]<-finite_num(raw[[score_cols[j]]][i])
  } else {
    mode<-'wide'; if(!row_col%in%names(raw)) fail('row_column not found',row_col); if(!length(metric_cols)) metric_cols<-setdiff(names(raw)[vapply(raw,function(x)any(is.finite(finite_num(x))),logical(1))],c(row_col,score_cols)); metric_cols<-intersect(metric_cols,names(raw)); if(!length(metric_cols)) fail('No metric columns selected')
    missing_scores<-setdiff(score_cols,names(raw)); if(length(missing_scores)) fail('score_columns not found',paste(missing_scores,collapse=', ')); rows<-as.character(raw[[row_col]]); rows[is.na(rows)|!nzchar(rows)]<-paste0('row_',which(is.na(rows)|!nzchar(rows))); mat<-matrix(NA_real_,nrow(raw),length(metric_cols),dimnames=list(rows,metric_cols)); for(j in seq_along(metric_cols)) mat[,j]<-finite_num(raw[[metric_cols[j]]]); score_mat<-matrix(NA_real_,nrow(raw),length(score_cols),dimnames=list(rows,score_cols)); for(j in seq_along(score_cols)) score_mat[,j]<-finite_num(raw[[score_cols[j]]])
  }
  if(!is.null(op$scores)&&nzchar(op$scores)&&file.exists(op$scores)) { sd<-readtab(op$scores); sid<-one(get(p,'score_row_column',names(sd)[1]),names(sd)[1]); sv<-one(get(p,'score_value_column',names(sd)[2]),names(sd)[2]); if(!all(c(sid,sv)%in%names(sd))) fail('Score file columns not found',paste(c(sid,sv),collapse=', ')); if(!length(score_cols)) score_cols<-sv; if(length(score_cols)!=1) fail('External scores support one score column at a time','Use score_columns in the main input for multiple scores'); score_mat[,1]<-setNames(finite_num(sd[[sv]]),as.character(sd[[sid]]))[rows] }
  if(!length(rows)||!length(metric_cols)) fail('Input has no rows or metrics')
  keep<-rep(TRUE,length(rows)); inc<-vec(get(p,'rows_include')); exc<-vec(get(p,'rows_exclude')); if(length(inc)) keep<-rows%in%inc; if(length(exc)) keep<-keep&!rows%in%exc; rows<-rows[keep]; mat<-mat[keep,,drop=FALSE]; score_mat<-score_mat[keep,,drop=FALSE]; if(!length(rows)) fail('No rows remain after filtering')
  mo<-vec(get(p,'metric_order')); if(length(mo)) metric_cols<-c(intersect(mo,metric_cols),setdiff(metric_cols,mo)); ro<-vec(get(p,'row_order')); if(length(ro)) rows<-c(intersect(ro,rows),setdiff(rows,ro)); if(boo(get(p,'sort_rows'),FALSE)) rows<-sort(rows); if(boo(get(p,'sort_by_score'),FALSE)) rows<-rows[order(score_mat[rows,1],decreasing=TRUE,na.last=TRUE)]; mat<-mat[rows,metric_cols,drop=FALSE]; score_mat<-score_mat[rows,,drop=FALSE]
  if(boo(get(p,'transpose'),FALSE)) { old<-rows; rows<-metric_cols; metric_cols<-old; mat<-t(mat); score_mat<-matrix(NA_real_,length(rows),length(score_cols),dimnames=list(rows,score_cols)) }
  if(tolower(one(get(p,'na_action','keep'),'keep'))=='drop') { ok<-apply(mat,1,function(x)any(is.finite(x)))|apply(score_mat,1,function(x)any(is.finite(x))); rows<-rows[ok]; mat<-mat[ok,,drop=FALSE]; score_mat<-score_mat[ok,,drop=FALSE] }; if(!length(rows)) fail('No rows remain after NA handling')
  left_lim<-as.numeric(unlist(get(p,'left_limits',NULL))); if(length(left_lim)!=2) left_lim<-range(mat,finite=TRUE); if(!all(is.finite(left_lim))) left_lim<-c(0,1); if(diff(left_lim)==0) left_lim<-left_lim+c(-.5,.5); left_pal<-vec(get(p,'left_colors',c('#3B4CC0','#F7F7F7','#B40426'))); if(length(left_pal)<2) left_pal<-c('#3B4CC0','#B40426')
  sc_order<-vec(get(p,'score_column_order')); if(length(sc_order)) score_cols<-c(intersect(sc_order,score_cols),setdiff(score_cols,sc_order)); score_mat<-score_mat[,score_cols,drop=FALSE]; k<-length(score_cols)
  titles<-vapply(seq_len(k),function(i) one(named_item(get(p,'score_titles',NULL),score_cols[i],i),score_cols[i]),character(1)); geoms<-tolower(vapply(seq_len(k),function(i) one(named_item(get(p,'score_geoms',get(p,'score_geom','bar')),score_cols[i],i),'bar'),character(1))); geoms[!geoms%in%c('bar','lollipop','point','label')]<-'bar'
  limits<-lapply(seq_len(k),function(i)as_limits(get(p,'score_limits',NULL),i,score_mat[,i])); palettes<-lapply(seq_len(k),function(i)as_palette(get(p,'score_color_sets',get(p,'score_colors',NULL)),i,c('#FFF3B0','#F4A261','#D95F02'))); alphas<-vapply(seq_len(k),function(i)num(named_item(get(p,'score_alphas',get(p,'score_alpha',.9)),score_cols[i],i),.9),numeric(1)); borders<-vapply(seq_len(k),function(i)one(named_item(get(p,'score_borders',get(p,'score_border','#D17A00')),score_cols[i],i),'#D17A00'),character(1)); digits<-vapply(seq_len(k),function(i)as.integer(num(named_item(get(p,'score_label_digits',get(p,'score_label_digit',2)),score_cols[i],i),2)),integer(1)); label_show<-vapply(seq_len(k),function(i)boo(named_item(get(p,'score_label_show',TRUE),score_cols[i],i),TRUE),logical(1)); panel_widths<-vapply(seq_len(k),function(i)num(named_item(get(p,'score_panel_widths',get(p,'score_panel_width',2.4)),score_cols[i],i),2.4),numeric(1))
  y<-match(rows,rev(rows)); n<-length(rows); m<-length(metric_cols); left_gap<-num(get(p,'left_right_gap',.8),.8); panel_gap<-num(get(p,'score_panel_gap',.35),.35); score_x0<-m+left_gap+1; panel_starts<-score_x0+c(0,cumsum(panel_widths+panel_gap)[-k]); panel_ends<-panel_starts+panel_widths; x_max<-max(panel_ends)+1
  z<-expand.grid(row=rows,metric=metric_cols,stringsAsFactors=FALSE); z$value<-as.vector(t(mat)); z$x<-match(z$metric,metric_cols); z$y<-match(z$row,rev(rows)); z$label<-fmt(z$value,as.integer(num(get(p,'left_label_digits',2),2))); z$hover<-sprintf('Row: %s<br>Metric: %s<br>Value: %s<br>Score: %s',z$row,z$metric,ifelse(is.na(z$value),'missing',z$label),fmt(score_mat[z$row,1],digits[1]))
  if(!boo(get(p,'score_scale_independent',TRUE),TRUE)) { common<-range(score_mat,finite=TRUE); if(!all(is.finite(common))) common<-c(0,1); if(diff(common)==0) common<-common+c(-.5,.5); limits<-rep(list(common),k); palettes<-rep(list(palettes[[1]]),k) }
  score_colour<-function(v,lim,pal) { z<-ifelse(is.finite(v),pmax(0,pmin(1,(v-lim[1])/diff(lim))),NA_real_); out<-rep('#D9D9D9',length(v)); ok<-is.finite(z); out[ok]<-grDevices::colorRampPalette(pal)(101)[pmax(1,pmin(101,floor(z[ok]*100)+1))]; out }
  sd<-do.call(rbind,lapply(seq_len(k),function(j){ v<-score_mat[rows,j]; lim<-limits[[j]]; norm<-pmax(0,pmin(1,(v-lim[1])/diff(lim))); direction<-tolower(one(named_item(get(p,'score_direction','forward'),score_cols[j],j),'forward')); if(direction%in%c('reverse','descending','lower_better')) norm<-1-norm; data.frame(row=rows,score_column=score_cols[j],score=v,y=y,panel=j,x0=panel_starts[j],xend=panel_starts[j]+norm*panel_widths[j],label=fmt(v,digits[j]),score_color=score_colour(v,lim,palettes[[j]]),fill_value=v,title=titles[j],stringsAsFactors=FALSE) })); sd$hover<-sprintf('Row: %s<br>Score column: %s<br>Score: %s',sd$row,sd$score_column,sd$label)
  write.csv(z[,c('row','metric','value')],file.path(out,'matrix_data_used.csv'),row.names=FALSE); write.csv(sd[,c('row','score_column','score')],file.path(out,'score_data_used.csv'),row.names=FALSE); write.csv(data.frame(row=rows,order=seq_along(rows)),file.path(out,'row_order.csv'),row.names=FALSE)
  left_geom<-tolower(one(get(p,'left_geom','circle'))); if(!left_geom%in%c('circle','diamond','square')) left_geom<-'circle'; shape<-c(circle=21,diamond=23,square=22)[[left_geom]]; g<-ggplot()+geom_point(data=z,aes(x=x,y=y,colour=value),shape=shape,size=num(get(p,'left_size',7),7),alpha=num(get(p,'left_alpha',.9),.9),stroke=num(get(p,'left_stroke_width',.35),.35),fill=NA)+scale_colour_gradientn(colours=left_pal,limits=left_lim,na.value=one(get(p,'left_na_color','#D9D9D9'),'#D9D9D9'),name=one(get(p,'left_legend_title','Left metrics'),'Left metrics'))
  if(boo(get(p,'left_label_show',TRUE),TRUE)) g<-g+geom_text(data=z,aes(x=x,y=y,label=label),colour=one(get(p,'left_label_color','#111111'),'#111111'),size=num(get(p,'left_label_size',3),3))
  for(j in seq_len(k)) { a<-sd[sd$panel==j,,drop=FALSE]; if(geoms[j]=='bar') g<-g+geom_rect(data=a,aes(xmin=x0,xmax=xend,ymin=y-.16,ymax=y+.16,fill=fill_value),alpha=alphas[j],colour=borders[j],linewidth=num(get(p,'score_border_width',.25),.25)) else if(geoms[j]=='lollipop') g<-g+geom_segment(data=a,aes(x=x0,y=y,xend=xend,yend=y),colour=borders[j],linewidth=1)+geom_point(data=a,aes(x=xend,y=y,fill=fill_value),shape=21,size=num(get(p,'score_size',5),5),colour=borders[j]) else if(geoms[j]=='point') g<-g+geom_point(data=a,aes(x=xend,y=y,fill=fill_value),shape=21,size=num(get(p,'score_size',5),5),colour=borders[j]) else g<-g+geom_text(data=a,aes(x=xend,y=y,label=label),hjust=0,colour=borders[j],size=num(get(p,'score_label_size',3),3)); if(label_show[j]) g<-g+geom_text(data=a,aes(x=pmax(xend+.06,x0+.06),y=y,label=label),hjust=0,colour=one(get(p,'score_label_color','#7A3E00'),'#7A3E00'),size=num(get(p,'score_label_size',3),3)) }
  # Each panel gets its own fill legend through a stable manual color proxy; left colour remains separate.
  score_values<-unlist(score_mat); score_palette<-grDevices::colorRampPalette(unlist(palettes))(101); g<-g+scale_fill_gradientn(colours=score_palette,limits=range(score_values,finite=TRUE),name=if(k==1)titles[1] else 'Scores',na.value='#D9D9D9')+scale_x_continuous(breaks=seq_len(m),labels=metric_cols,limits=c(.5,x_max),position='top',expand=c(0,0))+scale_y_continuous(breaks=seq_len(n),labels=rev(rows),trans='reverse',expand=c(0,0))+labs(title=if(boo(get(p,'title_show',TRUE),TRUE))one(get(p,'title','Interactive Bubble Score Matrix'),'Interactive Bubble Score Matrix')else NULL,subtitle=one(get(p,'subtitle',''),''),x=one(get(p,'xlab',''),''),y=one(get(p,'ylab','')))+theme_minimal(base_size=num(get(p,'base_size',11),11),base_family=one(get(p,'font_family','sans'),'sans'))+theme(panel.grid=element_blank(),panel.background=element_rect(fill=one(get(p,'background','#FFFFFF'),'#FFFFFF'),colour=NA),plot.background=element_rect(fill=one(get(p,'background','#FFFFFF'),'#FFFFFF'),colour=NA),axis.text.x=element_text(angle=num(get(p,'metric_header_angle',45),45),hjust=1,size=num(get(p,'metric_header_size',9),9)),axis.text.y=element_text(size=num(get(p,'row_label_size',10),10)),legend.position=if(boo(get(p,'legend_show',TRUE),TRUE))one(get(p,'legend_position','right'),'right')else'none',plot.margin=margin(num(get(p,'margin_top',12),12),num(get(p,'margin_right',16),16),num(get(p,'margin_bottom',10),10),num(get(p,'margin_left',10),10)))
  if(boo(get(p,'row_separator_show',TRUE),TRUE)) g<-g+geom_hline(yintercept=seq(.5,n-.5,1),colour=one(get(p,'row_separator_color','#999999'),'#999999'),linetype=one(get(p,'row_separator_linetype','dotted'),'dotted'),linewidth=num(get(p,'row_separator_width',.35),.35)); if(boo(get(p,'panel_border_show',FALSE),FALSE)) g<-g+theme(panel.border=element_rect(colour=one(get(p,'panel_border_color','#555555'),'#555555'),fill=NA)); g<-g+annotate('segment',x=m+.5+left_gap/2,xend=m+.5+left_gap/2,y=.5,yend=n+.5,colour='#666666',linewidth=.5)
  if(boo(get(p,'score_panel_title_show',TRUE),TRUE)) for(j in seq_len(k)) g<-g+annotate('text',x=mean(c(panel_starts[j],panel_ends[j])),y=0,label=titles[j],vjust=2,angle=num(get(p,'score_panel_title_angle',0),0),size=num(get(p,'score_panel_title_size',3.2),3.2)); for(j in seq_len(k-1)) g<-g+annotate('segment',x=panel_ends[j]+panel_gap/2,xend=panel_ends[j]+panel_gap/2,y=.5,yend=n+.5,colour=one(get(p,'score_panel_border_color','#B0B0B0'),'#B0B0B0'),linewidth=.35)
  W<-num(get(p,'width',max(8,m*.65+sum(panel_widths)+k)),max(8,m*.65+sum(panel_widths)+k)); H<-num(get(p,'height',max(4.5,n*.38+2)),max(4.5,n*.38+2)); dpi<-num(get(p,'dpi',300),300); for(ext in c('svg','pdf','png')) ggsave(file.path(out,paste0('result.',ext)),g,width=W,height=H,units='in',dpi=dpi)
  html<-file.path(out,'result.html'); if(boo(get(p,'interactive',TRUE),TRUE)&&requireNamespace('plotly',quietly=TRUE)&&requireNamespace('htmlwidgets',quietly=TRUE)) { pl<-plotly::plot_ly(); pl<-plotly::add_trace(pl,data=z,x=~x,y=~y,type='scatter',mode='markers+text',text=if(boo(get(p,'left_label_show',TRUE),TRUE))~label else NULL,textposition='middle center',marker=list(size=num(get(p,'left_size',7),7)*1.5,color=~value,colorscale='RdBu',reversescale=TRUE,cmin=left_lim[1],cmax=left_lim[2],showscale=TRUE,colorbar=list(title='Left metrics')),hovertext=~hover,hoverinfo='text',name='Metrics')
    for(j in seq_len(k)) { a<-sd[sd$panel==j,,drop=FALSE]; if(geoms[j]=='bar') { bar<-data.frame(x=c(rep(panel_starts[j],n),a$xend),y=c(a$y,a$y),score=c(a$score,a$score),hover=c(a$hover,a$hover)); pl<-plotly::add_trace(pl,data=bar,x=~x,y=~y,type='scatter',mode='lines',line=list(width=7,color='#D17A00'),text=~hover,hoverinfo='text',name=titles[j]) } else pl<-plotly::add_trace(pl,data=a,x=~xend,y=~y,type='scatter',mode='markers',marker=list(size=8,color=~score,colorscale='YlOrBr',cmin=limits[[j]][1],cmax=limits[[j]][2],showscale=TRUE,colorbar=list(title=titles[j],x=1+0.05*j)),text=~hover,hoverinfo='text',name=titles[j]) }
    tickvals<-c(seq_len(m),unlist(lapply(seq_len(k),function(j)mean(c(panel_starts[j],panel_ends[j]))))); ticktext<-c(metric_cols,titles); pl<-plotly::layout(pl,title=one(get(p,'title','Interactive Bubble Score Matrix'),'Interactive Bubble Score Matrix'),xaxis=list(tickvals=tickvals,ticktext=ticktext,range=c(.5,x_max)),yaxis=list(tickvals=seq_len(n),ticktext=rev(rows),autorange='reversed')); pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo(get(p,'zoom',TRUE),TRUE),modeBarButtonsToAdd=if(boo(get(p,'lasso_select',FALSE),FALSE))c('lasso2d','select2d')else character()); htmlwidgets::saveWidget(pl,html,selfcontained=TRUE) } else writeLines('<html><body><p>Interactive rendering requires the R packages plotly and htmlwidgets.</p></body></html>',html)
  per_score<-lapply(seq_len(k),function(j)list(column=score_cols[j],title=titles[j],limits=limits[[j]],palette=palettes[[j]],panel_width=panel_widths[j],geometry=geoms[j],alpha=alphas[j],label_show=label_show[j])); meta<-list(plugin='interactive_bubble_score_matrix',source_engine='ggplot2/plotly',input_mode=mode,row_column=row_col,metric_columns=metric_cols,score_column=if(k==1)score_cols[1]else NULL,score_columns=score_cols,score_panels=per_score,row_order=rows,left_scale=list(limits=left_lim,palette=left_pal),panel_widths=list(left=num(get(p,'left_panel_width',max(4,m)),max(4,m)),left_right_gap=left_gap,score_panel_gap=panel_gap,score=panel_widths),score_scale_independent=TRUE,outputs=required); writeLines(toJSON(meta,auto_unbox=TRUE,pretty=TRUE,null='null'),file.path(out,'figure.json')); unlink(file.path(out,'error.json')); logmsg(sprintf('Completed %d rows x %d metrics and %d scores.',n,m,k))
},error=function(e)fail('Interactive bubble score matrix failed',conditionMessage(e)))
